import{_ as a,o as t,c as e,aj as r}from"./framework.js";const p=JSON.parse('{"title":"组织管理 | Cms / Manual | Documentation","description":"组织管理 in Kooboo: 每个 Kooboo 账号都有自己的组织，账号本人是组织管理员。管理员可添加成员；成员切换到某组织后，即可管理该组织下有权限的站点。","frontmatter":{"title":"组织管理 | Cms / Manual | Documentation","description":"组织管理 in Kooboo: 每个 Kooboo 账号都有自己的组织，账号本人是组织管理员。管理员可添加成员；成员切换到某组织后，即可管理该组织下有权限的站点。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/manual/org.html"}]]},"headers":[],"relativePath":"zh/cms/manual/org.md","filePath":"cms/manual/org.md","lastUpdated":1793030278000}'),n={name:"zh/cms/manual/org.md"};function s(l,o,i,c,h,d){return t(),e("div",null,[...o[0]||(o[0]=[r('<h1 id="组织管理" tabindex="-1">组织管理 <a class="header-anchor" href="#组织管理" aria-label="Permalink to &quot;组织管理&quot;">​</a></h1><p>每个 Kooboo 账号都有自己的组织，账号本人是组织管理员。管理员可添加成员；成员切换到某组织后，即可管理该组织下有权限的站点。</p><h2 id="添加成员" tabindex="-1">添加成员 <a class="header-anchor" href="#添加成员" aria-label="Permalink to &quot;添加成员&quot;">​</a></h2><p>有两个入口：</p><ul><li>点右上角用户名，再点下拉里的第二个选项（当前组织名称）。</li><li>在账号主页打开 <strong>账号设置 → 组织 → 更多</strong>。</li></ul><p>进入后，输入对方的 Kooboo <strong>用户名</strong>，即可把该用户加入本组织。</p><h2 id="切换组织" tabindex="-1">切换组织 <a class="header-anchor" href="#切换组织" aria-label="Permalink to &quot;切换组织&quot;">​</a></h2><p>在账号主页打开 <strong>账号设置 → 组织</strong>，勾选要进入的组织，再点 <strong>切换组织</strong>。系统会退出登录；重新登录后进入所选组织，即可操作该组织下有权限的站点，或在该组织下创建站点。</p><h2 id="添加成员为站点用户" tabindex="-1">添加成员为站点用户 <a class="header-anchor" href="#添加成员为站点用户" aria-label="Permalink to &quot;添加成员为站点用户&quot;">​</a></h2><p>成员加入组织后，通常还要在站点里分配权限，对方才能打开指定站点。</p><p>打开 <strong>站点设置 → 用户管理</strong>，点 <strong>添加用户</strong>，选择用户与角色即可。该用户会获得所选角色对应的站点权限。</p>',11)])])}const u=a(n,[["render",s]]);export{p as __pageData,u as default};
